def m(gaji, tunj=0, **kw):
    d = {"gaji": gaji, "tunjangan_tetap": tunj}
    d.update(kw)
    return d


def full(gaji, tunj, extra=None, months=range(1, 13), change=None):
    """Monthly dict; `extra` maps month -> extra components; `change` maps first month -> (gaji, tunj)."""
    out = {}
    g, t = gaji, tunj
    for mo in months:
        if change and mo in change:
            g, t = change[mo]
        out[mo] = m(g, t, **((extra or {}).get(mo, {})))
    return out


